import{_ as o}from"./chunks/plugin-vue_export-helper.DlAUqK2U.js";import{c as a,o as t,af as r}from"./chunks/mermaid.DEOxUarQ.js";import"./chunks/cytoscape.C2CwDKBM.js";import"./chunks/dayjs.C32PoDnw.js";const f=JSON.parse('{"title":"Coze glossary","description":"Align Coze, Coze Programming, agent, workflow, skill, plugin, Studio, and Loop. Spell out what each is not, including Doubao, Trae, and vendor CLIs.","frontmatter":{"title":"Coze glossary","description":"Align Coze, Coze Programming, agent, workflow, skill, plugin, Studio, and Loop. Spell out what each is not, including Doubao, Trae, and vendor CLIs.","domain":"product","tags":["agent-builder"],"role":"glossary"},"headers":[],"relativePath":"products/coze/coze-glossary.md","filePath":"products/coze/coze-glossary.md","lastUpdated":1787110548000}'),n={name:"products/coze/coze-glossary.md"};function s(l,e,i,d,p,c){return t(),a("div",null,[...e[0]||(e[0]=[r(`<h1 id="coze-glossary" tabindex="-1">Coze glossary <a class="header-anchor" href="#coze-glossary" aria-label="Permalink to &quot;Coze glossary&quot;">​</a></h1><p>What each name <strong>is</strong> and <strong>is not</strong>. Clicks: <a href="./coze.html">tutorial</a>, <a href="./coze-cookbook.html">cookbook</a>. Parameters: <a href="./coze-cheatsheet.html">cheatsheet</a>.</p><h2 id="map" tabindex="-1">Map <a class="header-anchor" href="#map" aria-label="Permalink to &quot;Map&quot;">​</a></h2><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>                    ByteDance AI</span></span>
<span class="line"><span>          ┌────────────┼────────────┐</span></span>
<span class="line"><span>       Doubao #79    Coze family       Trae #80</span></span>
<span class="line"><span>                         │             Ark #82</span></span>
<span class="line"><span>        ┌────────────────┼────────────────┐</span></span>
<span class="line"><span>        │                │                │</span></span>
<span class="line"><span>     Coze workspace  Coze Programming   Coze Loop</span></span>
<span class="line"><span>      (coze.cn)       (code.coze.cn)   prompt/eval/trace</span></span>
<span class="line"><span>        │                │                │</span></span>
<span class="line"><span>   Coze/cloud/local    low-code | AI      commercial</span></span>
<span class="line"><span>      agents           agents/workflows   Coze Loop OSS</span></span>
<span class="line"><span>                         │</span></span>
<span class="line"><span>                    Coze Studio OSS</span></span></code></pre></div><p>Plans sit above: personal / team / enterprise decide credits and collab. Building happens in Programming. Consumption happens in Coze. Eval happens in Loop.</p><hr><h2 id="coze" tabindex="-1">Coze <a class="header-anchor" href="#coze" aria-label="Permalink to &quot;Coze&quot;">​</a></h2><p><strong>What</strong>: Official definition — “a next-generation AI team collaboration platform for the Agent era” (<a href="https://docs.coze.cn/what_is_coze" target="_blank" rel="noreferrer">what_is_coze</a>). Web, macOS / Windows desktop, mobile.</p><p><strong>Not</strong>: the low-code canvas, Doubao, or Trae. In-chat AI programming only wraps web / app / mini program / import.</p><p><strong>Why it exists</strong>: humans and several agents need a shared project, files, calendar, mailbox, and cloud devices. That is not “ship a support bot.”</p><hr><h2 id="coze-programming" tabindex="-1">Coze Programming <a class="header-anchor" href="#coze-programming" aria-label="Permalink to &quot;Coze Programming&quot;">​</a></h2><p><strong>What</strong>: an AI-driven app platform for agents, workflows, skills, web, apps, and mini programs (<a href="https://docs.coze.cn/guides_welcome" target="_blank" rel="noreferrer">guides_welcome</a>). Host: <code>code.coze.cn</code>.</p><p><strong>Not</strong>: Trae. Not self-hostable (use Studio). The visual “low-code project” is an earlier surface, but new low-code agents still start here.</p><hr><h2 id="low-code-agent" tabindex="-1">Low-code agent <a class="header-anchor" href="#low-code-agent" aria-label="Permalink to &quot;Low-code agent&quot;">​</a></h2><p><strong>What</strong>: a conversational AI project. The model follows a persona and may call plugins / workflows / knowledge. Older docs say <strong>Bot</strong>.</p><p><strong>Not</strong>: a full-code AI-programming project, and not a template “Coze Agent” on the consumer workspace.</p><p><strong>Typical jobs</strong>: support, companion, assistant, tutor (<a href="https://docs.coze.cn/about-low-code-project" target="_blank" rel="noreferrer">about-low-code-project</a>).</p><hr><h2 id="full-code-agent" tabindex="-1">Full-code agent <a class="header-anchor" href="#full-code-agent" aria-label="Permalink to &quot;Full-code agent&quot;">​</a></h2><p><strong>What</strong>: a deployable project generated from the <strong>Agent</strong> tab on the Programming home (<a href="https://docs.coze.cn/guides_vibe_coding_agent" target="_blank" rel="noreferrer">guides_vibe_coding_agent</a>).</p><p><strong>Not</strong>: the drag-and-drop arrange page. Publish leans toward API hosting, not the same channel table as “WeChat customer service.”</p><hr><h2 id="workflow-chatflow" tabindex="-1">Workflow / chatflow <a class="header-anchor" href="#workflow-chatflow" aria-label="Permalink to &quot;Workflow / chatflow&quot;">​</a></h2><p><strong>What</strong>: executable node graphs. Workflows serve functions and data. Chatflows serve chatbots (<a href="https://docs.coze.cn/guides_workflow" target="_blank" rel="noreferrer">guides_workflow</a>).</p><p><strong>Not</strong>: a skill (skills do not lock the path) or a plugin (a plugin is one node type).</p><hr><h2 id="plugin" tabindex="-1">Plugin <a class="header-anchor" href="#plugin" aria-label="Permalink to &quot;Plugin&quot;">​</a></h2><p><strong>What</strong>: a set of same-domain API tools (<a href="https://docs.coze.cn/guides_plugin" target="_blank" rel="noreferrer">guides_plugin</a>).</p><p><strong>Not</strong>: a skill. A skill also says <em>when</em> and <em>how</em> to use the tools.</p><hr><h2 id="skill" tabindex="-1">Skill <a class="header-anchor" href="#skill" aria-label="Permalink to &quot;Skill&quot;">​</a></h2><p><strong>What</strong>: <code>SKILL.md</code> plus optional scripts / references / assets. Loaded progressively (<a href="https://docs.coze.cn/guides_skill_overview" target="_blank" rel="noreferrer">guides_skill_overview</a>).</p><p><strong>Not</strong>: the always-on system prompt, a fixed workflow, or MCP itself.</p><hr><h2 id="knowledge" tabindex="-1">Knowledge <a class="header-anchor" href="#knowledge" aria-label="Permalink to &quot;Knowledge&quot;">​</a></h2><p><strong>What</strong>: a developer-owned static retrieval store. Two products: Coze knowledge and Volcengine knowledge.</p><p><strong>Not</strong>: memory. Memory is per-user dynamic data and does not travel across agents.</p><hr><h2 id="coze-agent-cloud-agent-local-agent" tabindex="-1">Coze Agent / cloud Agent / local Agent <a class="header-anchor" href="#coze-agent-cloud-agent-local-agent" aria-label="Permalink to &quot;Coze Agent / cloud Agent / local Agent&quot;">​</a></h2><p>Consumer-side runtimes (<a href="https://docs.coze.cn/cozespace_agent_overview" target="_blank" rel="noreferrer">cozespace_agent_overview</a>):</p><table tabindex="0"><thead><tr><th>Type</th><th>Runs on</th><th>Use when</th></tr></thead><tbody><tr><td>Coze Agent</td><td>Native workspace</td><td>Office, creation, industry templates</td></tr><tr><td>Cloud Agent</td><td>Coze cloud computer</td><td>Claude Code / Codex / OpenClaw / Hermes frameworks without local ops</td></tr><tr><td>Local Agent</td><td>Your machine</td><td>Local files and toolchain</td></tr></tbody></table><p>Cloud frameworks are <strong>not</strong> the Anthropic or OpenAI apps. You cannot sign in to those accounts. Models come from Coze.</p><hr><h2 id="coze-cli" tabindex="-1">Coze CLI <a class="header-anchor" href="#coze-cli" aria-label="Permalink to &quot;Coze CLI&quot;">​</a></h2><p><strong>What</strong>: npm <code>@coze/cli</code>, binary <code>coze</code>. Turns Programming create / develop / deploy into commands for humans and agents.</p><p><strong>Not</strong>: part of Trae, and not the Coze desktop app. Trae is only an example Skill install target.</p><hr><h2 id="coze-loop" tabindex="-1">Coze Loop <a class="header-anchor" href="#coze-loop" aria-label="Permalink to &quot;Coze Loop&quot;">​</a></h2><p><strong>What</strong>: developer platform for prompts, evaluation, and traces (<a href="https://docs.coze.cn/cozeloop_what-is-cozeloop" target="_blank" rel="noreferrer">what is Loop</a>). Same subscription logic as Programming.</p><p><strong>Not</strong>: a builder canvas. OSS counterpart is Coze Loop; commercial Loop adds metrics and org controls.</p><hr><h2 id="coze-studio" tabindex="-1">Coze Studio <a class="header-anchor" href="#coze-studio" aria-label="Permalink to &quot;Coze Studio&quot;">​</a></h2><p><strong>What</strong>: open-source “all-in-one AI agent development tool,” Apache-2.0. Visual create / debug / deploy for agents, apps, and workflows.</p><p><strong>Not</strong>: commercial Programming. Studio is a single-node core without workspaces, enterprise orgs, or multi-user collab (<a href="https://docs.coze.cn/guides_FAQ" target="_blank" rel="noreferrer">FAQ</a>).</p><hr><h2 id="coze-pro-enterprise" tabindex="-1">Coze Pro / Enterprise <a class="header-anchor" href="#coze-pro-enterprise" aria-label="Permalink to &quot;Coze Pro / Enterprise&quot;">​</a></h2><p><strong>What</strong>: the Volcengine product page <a href="https://www.volcengine.com/product/coze-pro" target="_blank" rel="noreferrer">coze-pro</a> plus the enterprise plan rows (standard / flagship). Hybrid: subscription + usage.</p><p><strong>Not</strong>: a third canvas beside Programming. SSO / VPC follow <a href="https://docs.coze.cn/guides_edition" target="_blank" rel="noreferrer">guides_edition</a>.</p><hr><h2 id="doubao-trae-ark" tabindex="-1">Doubao / Trae / Ark <a class="header-anchor" href="#doubao-trae-ark" aria-label="Permalink to &quot;Doubao / Trae / Ark&quot;">​</a></h2><p><strong>What</strong>: other ByteDance AI products. Doubao is chat. Trae is an IDE. Ark is a model API.</p><p><strong>Not</strong>: this handbook’s build tutorial. A Doubao <em>model</em> in the persona is not the Doubao <em>product</em>. The Doubao <em>publish channel</em> is gone.</p><hr><h2 id="retired-or-renamed" tabindex="-1">Retired or renamed <a class="header-anchor" href="#retired-or-renamed" aria-label="Permalink to &quot;Retired or renamed&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Phrase</th><th>Now</th></tr></thead><tbody><tr><td>Bot</td><td>Low-code agent</td></tr><tr><td>Publish to Doubao</td><td>Entry closed 2026-07-01</td></tr><tr><td>Douyin avatar</td><td>Removed 2025-09-03</td></tr><tr><td>Workflow / image-flow store</td><td>Removed</td></tr><tr><td>Self-host Programming</td><td>Unsupported; use Studio</td></tr><tr><td>Clone a store agent’s full config</td><td>Store listings are private; use the template store</td></tr></tbody></table>`,67)])])}const b=o(n,[["render",s]]);export{f as __pageData,b as default};
